import unittest
from stock_balance import fold_balance

class StockBalance(unittest.TestCase):
    def test_initializer_is_first_operand(self):
        self.assertEqual(fold_balance([3, 2], 10), 5)
        self.assertEqual(fold_balance([7], 20), 13)
        self.assertEqual(fold_balance([2, -5, 4], 11), 10)

    def test_empty_iterable_returns_opening(self):
        self.assertEqual(fold_balance([], 41), 41)
        self.assertEqual(fold_balance(iter([]), 0), 0)

    def test_one_shot_input(self):
        debits = iter([5, 8, -2])
        self.assertEqual(fold_balance(debits, 30), 19)
        self.assertEqual(list(debits), [])

if __name__ == '__main__':
    unittest.main()

